from pysat.solvers import Glucose3

def solve_qg3_pysat(n):
    # Variables: x_i_j_v where i, j, v in 0..n-1
    # x_i_j_v is true if x[i][j] == v
    def var(i, j, v):
        return i * n * n + j * n + v + 1

    solver = Glucose3()

    # Each cell has exactly one value
    for i in range(n):
        for j in range(n):
            solver.add_clause([var(i, j, v) for v in range(n)])
            for v1 in range(n):
                for v2 in range(v1 + 1, n):
                    solver.add_clause([-var(i, j, v1), -var(i, j, v2)])

    # Latin square: rows
    for i in range(n):
        for v in range(n):
            solver.add_clause([var(i, j, v) for j in range(n)])
            for j1 in range(n):
                for j2 in range(j1 + 1, n):
                    solver.add_clause([-var(i, j1, v), -var(i, j2, v)])

    # Latin square: columns
    for j in range(n):
        for v in range(n):
            solver.add_clause([var(i, j, v) for i in range(n)])
            for i1 in range(n):
                for i2 in range(i1 + 1, n):
                    solver.add_clause([-var(i1, j, v), -var(i2, j, v)])

    # Idempotent
    for i in range(n):
        solver.add_clause([var(i, i, i)])

    # QG3: x[x[i][j]][x[j][i]] = i
    # x[i][j] = r, x[j][i] = c => x[r][c] = i
    # For all i, j, r, c:
    # (x[i][j] == r AND x[j][i] == c) => x[r][c] == i
    # Equivalent to:
    # NOT (x[i][j] == r AND x[j][i] == c) OR x[r][c] == i
    # -var(i, j, r) OR -var(j, i, c) OR var(r, c, i)
    for i in range(n):
        for j in range(n):
            for r in range(n):
                for c in range(n):
                    solver.add_clause([-var(i, j, r), -var(j, i, c), var(r, c, i)])

    if solver.solve():
        model = solver.get_model()
        result = [0] * (n * n)
        for i in range(n):
            for j in range(n):
                for v in range(n):
                    if model[var(i, j, v) - 1] > 0:
                        result[i * n + j] = v
        return result
    else:
        return None

